function newRosco(letters=ABC,levels=1,banks=1){return {schema:'roscolab.v1',id:uid(),title:'Mi nuevo rosco',subject:'Otra',course:'3º ESO',author:'',description:'',color:'#4f46e5',letters:[...letters],levels:Array.from({length:levels},(_,i)=>({name:['Básico','Intermedio','Avanzado','Experto'][i],banks:Array.from({length:banks},(_,j)=>({name:`Banco ${String.fromCharCode(65+j)}`,questions:letters.map(qblank)}))}))}}
function fits(q,a=q.answer){const w=norm(a),l=norm(q.letter);return !!w&&(q.mode==='starts'?w.startsWith(l):w.includes(l))}function issues(r){let out=[];for(let i=0;i<r.levels.length;i++){let across=new Map();for(let j=0;j<r.levels[i].banks.length;j++){let seen=new Set();for(const q of r.levels[i].banks[j].questions){const label=`${r.levels[i].name} / ${r.levels[i].banks[j].name} / ${q.letter}`;if(!q.clue.trim()||!q.answer.trim())out.push({label,msg:'Falta pregunta o respuesta',hard:true});else if(!fits(q))out.push({label,msg:'La respuesta no cumple la letra',hard:true});if(q.aliases.some(a=>!fits(q,a)||!norm(a)||norm(q.answer)!==norm(a)&&norm(q.answer).startsWith(norm(a))))out.push({label,msg:'Alternativa inválida o incompleta',hard:true});let n=norm(q.answer);if(n&&seen.has(n))out.push({label,msg:'Respuesta repetida en el banco',hard:true});if(n&&across.has(n)&&across.get(n)!==j)out.push({label,msg:'Respuesta repetida entre bancos del nivel',hard:false});if(n){seen.add(n);across.set(n,j)}}}}return out}
// Gameplay uses a temporary subset; drafts and stored questions remain intact.
function usableQuestions(bank){let seen=new Set();return bank.questions.filter(q=>{let n=norm(q.answer);if(!q.clue.trim()||!q.answer.trim()||!fits(q)||seen.has(n)||q.aliases.some(a=>!fits(q,a)||!norm(a)||norm(q.answer)!==norm(a)&&norm(q.answer).startsWith(norm(a))))return false;seen.add(n);return true})}
function playable(r){return r.levels.some(l=>l.banks.some(b=>usableQuestions(b).length>=2))}
function commonQuestions(lv,a,b){let aa=usableQuestions(lv.banks[a]);if(b==null)return [aa];let bb=usableQuestions(lv.banks[b]),letters=new Set(bb.map(q=>q.letter));aa=aa.filter(q=>letters.has(q.letter));let common=new Set(aa.map(q=>q.letter));return [aa,bb.filter(q=>common.has(q.letter))]}
function normalize(raw){if(raw&&raw.rosco)raw=raw.rosco;if(raw&&raw['1']?.green){const old=raw;raw={title:'Rosco importado',subject:'Otra',course:'Todos los niveles',letters:ABC,levels:Object.keys(old).filter(k=>/^\d+$/.test(k)).map(k=>({name:`Nivel ${k}`,banks:[{name:'Banco A',questions:old[k].green},{name:'Banco B',questions:old[k].white}]}))}}if(!raw||!Array.isArray(raw.letters)||!Array.isArray(raw.levels))throw Error('El JSON no contiene letters y levels. Utiliza el formato Rosco LAB.');const letters=raw.letters.map(l=>String(l).toUpperCase());if(letters.length<2||letters.length>27||new Set(letters).size!==letters.length||letters.some(l=>!ABC.includes(l)))throw Error('Selecciona de 2 a 27 letras españolas diferentes.');if(raw.levels.length<1||raw.levels.length>4)throw Error('Se admiten de 1 a 4 niveles.');let r={schema:'roscolab.v1',id:uid(),title:String(raw.title||'Rosco importado').slice(0,120),subject:String(raw.subject||'Otra').slice(0,80),course:String(raw.course||'Todos los niveles').slice(0,80),author:String(raw.author||'').slice(0,100),description:String(raw.description||'').slice(0,1000),color:/^#[0-9a-f]{6}$/i.test(raw.color)?raw.color:colors[raw.subject]||'#4f46e5',letters,levels:[]};r.levels=raw.levels.map((l,i)=>{if(!Array.isArray(l.banks)||l.banks.length<1||l.banks.length>4)throw Error(`Nivel ${i+1}: se admiten 1–4 bancos.`);return {name:String(l.name||`Nivel ${i+1}`).slice(0,80),banks:l.banks.map((b,j)=>{if(!Array.isArray(b.questions))throw Error('Falta questions en un banco.');let qs=b.questions;if(qs.length!==letters.length||new Set(qs.map(q=>String(q.letter).toUpperCase())).size!==letters.length||qs.some(q=>!letters.includes(String(q.letter).toUpperCase())))throw Error(`Nivel ${i+1}, banco ${j+1}: debe haber exactamente una pregunta por letra.`);return {name:String(b.name||`Banco ${j+1}`).slice(0,80),questions:letters.map(letter=>{let q=qs.find(q=>String(q.letter).toUpperCase()===letter);if(!['starts','contains'].includes(q.mode))throw Error(`Letra ${letter}: mode debe ser starts o contains.`);return {letter,mode:q.mode,clue:String(q.clue??'').slice(0,4000),answer:String(q.answer??'').slice(0,300),fact:String(q.fact??'').slice(0,4000),aliases:Array.isArray(q.aliases)?q.aliases.map(String).slice(0,20):[],source:String(q.source??'').slice(0,300)}})}})}});return r}
function wheelArt(){return `<svg viewBox="0 0 320 280" role="img" aria-label="Rosco multicolor de letras"><circle cx="160" cy="140" r="112" fill="none" stroke="#ffffff20" stroke-width="2"/><circle cx="160" cy="140" r="88" fill="#ffffff09"/>${ABC.map((l,i)=>{let a=i*2*Math.PI/ABC.length-Math.PI/2,x=160+112*Math.cos(a),y=140+112*Math.sin(a);return `<circle cx="${x}" cy="${y}" r="11" fill="${['#65d8e7','#929bff','#b2f0c9','#f9d285'][i%4]}"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="12" font-weight="800" fill="#15213a">${l}</text>`}).join('')}<text x="160" y="135" text-anchor="middle" fill="white" font-size="28" font-weight="800">¡A JUGAR!</text><text x="160" y="158" text-anchor="middle" fill="#c1d7f6" font-size="12">TODAS LAS MATERIAS</text></svg>`}
function card(r,personal=false){let n=issues(r).filter(x=>x.hard).length,ok=playable(r);return `<article class="tile" data-color style="--tile-color:${esc(r.color)}"><div class="row between"><span class="pill">${esc(r.subject)}</span><span class="muted">${r.letters.length} letras</span></div><h3>${esc(r.title)}</h3><p>${esc(r.description||r.course)}</p><div class="row"><span class="pill">${esc(r.course)}</span><span class="pill">${filledCount(r)} completas / ${count(r)} totales</span><span class="pill">${r.levels.length} nivel(es)</span></div>${personal?'<small class="muted">Mi rosco · guardado en este navegador</small>':''}${n?`<small class="${ok?'muted':'error'}">${n} incidencias · ${ok?'Se puede jugar con las letras válidas':'Necesita al menos 2 preguntas válidas en un banco'}</small>`:''}<div class="row"><button class="primary" data-play="${esc(r.id)}" ${ok?'':'disabled'}>${n&&ok?'Jugar con letras válidas':'Jugar'}</button><button data-edit="${esc(r.id)}">${personal?'Editar':'Duplicar'}</button>${personal?`<button data-export="${esc(r.id)}">JSON</button><button class="danger" data-delete="${esc(r.id)}">Eliminar</button>`:''}</div>${r.id==='andalucia'&&!portable?'<a href="andalucia/index.html">Abrir edición 4D original ↗</a>':''}</article>`}
function bindCards(){app.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>setup(byId(b.dataset.play)));app.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{let r=byId(b.dataset.edit);draft=clone(r);if(!mine.some(x=>x.id===r.id)){draft.id=uid();draft.title+=' · copia'}editLevel=editBank=0;dirty=false;go('editor',true)});app.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportJSON(byId(b.dataset.export)));app.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar este rosco guardado?')){mine=mine.filter(r=>r.id!==b.dataset.delete);if(!persist())toast('No se pudo actualizar el almacenamiento.');list(view==='mine')}})}
function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">Tu aula · tus preguntas · tu juego</div><h1>Crea. Juega.<br>Aprende.</h1><p>Convierte cualquier contenido en un rosco interactivo. Diseña tus preguntas, adapta juegos y prepara retos para tu clase.</p><div class="row"><button class="primary" id="heroPlay">Explorar roscos →</button><button class="secondary" id="heroCreate">Crear mi rosco</button><button class="secondary" id="heroPDF">Crear desde PDF</button></div></div>${wheelArt()}</section><div class="section-title"><div><h2>¿Qué quieres hacer hoy?</h2><p class="muted">Herramientas pensadas para el profesorado.</p></div></div><div class="grid">${[['◉','Jugar a un rosco','Descubre los juegos listos para usar.','library'],['✎','Crear manualmente','Personaliza letras, preguntas y niveles.','editor'],['✦','Crear con IA','Genera preguntas con tu IA favorita o prueba la generación local.','ai'],['▤','Mis roscos','Guarda, edita y exporta tus creaciones.','mine']].map(([s,t,d,n])=>`<article class="tile"><div class="symbol">${s}</div><h3>${t}</h3><p>${d}</p><button data-home="${n}">Abrir →</button></article>`).join('')}</div><div class="section-title"><div><h2>Roscos destacados</h2><p class="muted">Una biblioteca para todas las materias.</p></div><button id="all">Ver todos</button></div><div class="grid">${library.slice(0,4).map(r=>card(r)).join('')}</div>`;act('heroPlay',()=>go('library'));act('heroPDF',()=>{go('ai');switchAI(false)});act('heroCreate',()=>create());act('all',()=>go('library'));app.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>b.dataset.home==='editor'?create():go(b.dataset.home));bindCards()}
function list(personal){let arr=personal?mine:[...mine,...library];app.innerHTML=head(personal?'Tu espacio':'Recursos educativos',personal?'Mis roscos':'Biblioteca de roscos',personal?'Guardados en este navegador. Exporta copias para conservarlos y compartirlos.':'Juegos preparados y tus propios roscos guardados en este navegador.')+`<div class="panel row no-print"><input id="search" placeholder="Buscar por tema, materia, curso…" style="flex:2;min-width:180px"><select id="filter" style="flex:1;min-width:150px"><option value="">Todas las materias</option>${options([...new Set(arr.map(x=>x.subject))])}</select><button class="primary" id="create">+ Crear rosco</button><button id="import">Importar JSON</button><input type="file" id="file" accept=".json,application/json" hidden></div><div id="results" class="grid" style="margin-top:16px"></div>`;function render(){let s=norm(val('search')),f=val('filter');let items=arr.filter(r=>(!f||r.subject===f)&&norm([r.title,r.subject,r.course,r.description,r.author].join(' ')).includes(s));$('results').innerHTML=items.length?items.map(r=>card(r,personal||mine.some(x=>x.id===r.id))).join(''):'<div class="panel">No hay roscos que coincidan. Crea uno nuevo o importa un archivo.</div>';bindCards()}$('search').oninput=render;$('filter').onchange=render;act('create',create);act('import',()=>$('file').click());$('file').onchange=async()=>{try{importText(await $('file').files[0].text())}catch(e){toast(e.message)}};render()}
function create(){if(view==='editor'&&dirty&&!confirm('¿Descartar cambios sin guardar?'))return;draft=newRosco();editLevel=editBank=0;dirty=false;go('editor',true)}
function lettersHTML(letters){return `<div class="letterpick" id="letterpick">${ABC.map(l=>`<label><input type="checkbox" value="${l}" ${letters.includes(l)?'checked':''} aria-label="Letra ${l}">${l}</label>`).join('')}</div><div class="row" style="margin-top:8px"><button id="lettersAll">27 letras</button><button id="lettersEasy">23 sin K, W, X, Ñ</button><button id="lettersShort">10 letras</button></div>`}function bindLetters(){for(const [id,ls] of [['lettersAll',ABC],['lettersEasy',ABC.filter(l=>!['K','W','X','Ñ'].includes(l))],['lettersShort',[...'ABCDEFGHIJ']]])act(id,()=>{app.querySelectorAll('#letterpick input').forEach(x=>x.checked=ls.includes(x.value));if(view==='ai')updatePrompt()})}function picked(){return ABC.filter(l=>[...app.querySelectorAll('#letterpick input:checked')].some(x=>x.value===l))}
function syncEditor(){if(!$('edTitle'))return;draft.title=val('edTitle').trim()||'Mi nuevo rosco';draft.subject=val('edSubject');draft.course=val('edCourse');draft.author=val('edAuthor');draft.description=val('edDescription');draft.color=val('edColor');let lv=draft.levels[editLevel],bank=lv.banks[editBank];lv.name=val('levelName')||`Nivel ${editLevel+1}`;bank.name=val('bankName')||`Banco ${editBank+1}`;app.querySelectorAll('tr[data-q]').forEach((tr,i)=>{let q=bank.questions[i];for(let k of ['clue','answer','mode','fact','source'])q[k]=tr.querySelector(`[data-field="${k}"]`).value;q.aliases=tr.querySelector('[data-field="aliases"]').value.split(';').map(x=>x.trim()).filter(Boolean)})}
function renderEditor(){accent(draft);let r=draft,lv=r.levels[editLevel],b=lv.banks[editBank];app.innerHTML=head('Taller docente','Editor universal','Configura el rosco, revisa las preguntas y guarda tu trabajo.')+`<div class="stack"><section class="panel"><h2>1. Identidad del juego</h2><div class="fields" style="margin-top:12px">${field('Título','edTitle',r.title)}<label class="field"><span>Materia</span><input id="edSubject" list="subjects" value="${esc(r.subject)}"><datalist id="subjects">${options(Object.keys(colors))}</datalist></label>${sel('Curso','edCourse',[...new Set([...courses,r.course])],r.course)}${field('Autoría (opcional)','edAuthor',r.author)}${field('Color del juego','edColor',r.color,'color')}</div><label class="field"><span>Descripción</span><textarea id="edDescription" rows="2">${esc(r.description)}</textarea></label></section><section class="panel"><h2>2. Letras, niveles y bancos</h2><p class="muted">Elige qué letras utilizar. Para duelo necesitas al menos dos bancos en el mismo nivel.</p>${lettersHTML(r.letters)}<div class="row" style="margin-top:12px"><button id="applyLetters">Aplicar selección de letras</button><button id="addLevel" ${r.levels.length>=4?'disabled':''}>+ Nivel</button><button id="removeLevel" ${r.levels.length<=1?'disabled':''}>− Nivel actual</button><button id="addBank" ${lv.banks.length>=4?'disabled':''}>+ Banco</button><button id="removeBank" ${lv.banks.length<=1?'disabled':''}>− Banco actual</button></div></section><section class="panel"><div class="row between"><h2>3. Preguntas</h2><span class="pill">${filledCount(r)} completas / ${count(r)} totales</span></div><div class="notice" style="margin:12px 0">${filledByLevel(r).map(x=>`<div><strong>Nivel ${x.level} · ${esc(x.name)}</strong>: ${x.filled}/${x.total} completas${x.banks.length>1?` · ${x.banks.map(b=>`${esc(b.name)} ${b.filled}/${b.total}`).join(' · ')}`:''}</div>`).join('')}</div><div class="fields" style="margin:12px 0"><label class="field"><span>Nivel</span><select id="levelSelect">${r.levels.map((l,i)=>`<option value="${i}" ${i===editLevel?'selected':''}>${i+1}. ${esc(l.name)}</option>`).join('')}</select></label>${field('Nombre del nivel','levelName',lv.name)}<label class="field"><span>Banco</span><select id="bankSelect">${lv.banks.map((l,i)=>`<option value="${i}" ${i===editBank?'selected':''}>${i+1}. ${esc(l.name)}</option>`).join('')}</select></label>${field('Nombre del banco','bankName',b.name)}</div><div class="scroll"><table style="min-width:950px"><thead><tr><th>Letra</th><th>Tipo</th><th style="width:28%">Pregunta</th><th style="width:17%">Respuesta</th><th>Alternativas (;)</th><th>Explicación</th><th>Fuente / pág.</th></tr></thead><tbody>${b.questions.map(q=>`<tr data-q="${q.letter}"><td>${q.letter}</td><td><select data-field="mode" aria-label="Tipo ${q.letter}"><option value="starts" ${q.mode==='starts'?'selected':''}>Empieza por</option><option value="contains" ${q.mode==='contains'?'selected':''}>Contiene</option></select></td><td><textarea data-field="clue" aria-label="Pregunta ${q.letter}">${esc(q.clue)}</textarea></td><td><input data-field="answer" aria-label="Respuesta ${q.letter}" value="${esc(q.answer)}"></td><td><input data-field="aliases" aria-label="Alternativas ${q.letter}" value="${esc(q.aliases.join('; '))}"></td><td><textarea data-field="fact" aria-label="Explicación ${q.letter}">${esc(q.fact)}</textarea></td><td><input data-field="source" aria-label="Fuente ${q.letter}" value="${esc(q.source||'')}"></td></tr>`).join('')}</tbody></table></div><div id="repairPanel" class="hidden stack" style="margin-top:16px"></div><div id="saveStatus" role="status" aria-live="polite" class="muted"></div><div id="audit" class="notice" style="margin-top:12px">Verifica las respuestas antes de jugar.</div></section><div class="toolbar row"><button class="primary" id="save">Guardar rosco</button><button id="openMine">Mis roscos</button><button id="verify">Verificar preguntas</button><button id="repairAI">Completar / mejorar con IA</button><button id="playDraft">Jugar</button><button id="exportDraft">Exportar JSON</button><button id="exportHtml">Descargar HTML autónomo</button><button id="printDraft">Solucionario</button><button id="newDraft">Nuevo</button></div></div>`;bindLetters();app.oninput=()=>{if(view==='editor')dirty=true};$('edSubject').onchange=()=>{$('edColor').value=colors[val('edSubject')]||'#4f46e5';dirty=true};$('levelSelect').onchange=()=>{syncEditor();editLevel=Number(val('levelSelect'));editBank=0;renderEditor()};$('bankSelect').onchange=()=>{syncEditor();editBank=Number(val('bankSelect'));renderEditor()};act('applyLetters',()=>{syncEditor();let ls=picked();if(ls.length<2)return toast('Selecciona al menos dos letras.');if(r.letters.some(l=>!ls.includes(l))&&!confirm('Se eliminarán las preguntas de las letras desmarcadas. ¿Continuar?'))return;r.letters=ls;r.levels.forEach(l=>l.banks.forEach(b=>b.questions=ls.map(x=>b.questions.find(q=>q.letter===x)||qblank(x))));dirty=true;renderEditor()});act('addLevel',()=>{syncEditor();r.levels.push(newRosco(r.letters).levels[0]);editLevel=r.levels.length-1;r.levels[editLevel].name=`Nivel ${editLevel+1}`;editBank=0;dirty=true;renderEditor()});act('removeLevel',()=>{if(confirm('¿Eliminar el nivel y sus preguntas?')){syncEditor();r.levels.splice(editLevel,1);editLevel=editBank=0;dirty=true;renderEditor()}});act('addBank',()=>{syncEditor();lv.banks.push({name:`Banco ${String.fromCharCode(65+lv.banks.length)}`,questions:r.letters.map(qblank)});editBank=lv.banks.length-1;dirty=true;renderEditor()});act('removeBank',()=>{if(confirm('¿Eliminar el banco y sus preguntas?')){syncEditor();lv.banks.splice(editBank,1);editBank=0;dirty=true;renderEditor()}});act('verify',audit);act('repairAI',showRepair);act('openMine',()=>go('mine'));act('save',()=>{syncEditor();let summary=filledByLevel(r),filled=filledCount(r),total=count(r),emptyLevels=summary.filter(x=>x.filled===0).map(x=>`Nivel ${x.level} (${x.name})`);let next=mine.slice(),i=next.findIndex(x=>x.id===r.id);if(i<0)next.push(clone(r));else next[i]=clone(r);if(!write(DB,next)){ $('saveStatus').textContent='No se pudo guardar. Exporta JSON para conservarlo.';dirty=true;toast('No se pudo guardar en el navegador. Exporta JSON.');return}mine=read(DB,next);dirty=false;let msg=`Rosco guardado: ${filled} preguntas completas de ${total}. Disponible en Mis roscos y Biblioteca.`;$('saveStatus').innerHTML=msg+(emptyLevels.length?` <br><small class="muted">Sin contenido completo: ${esc(emptyLevels.join(', '))}.</small>`:'');toast('Rosco guardado correctamente.');audit()});act('playDraft',()=>{syncEditor();if(!playable(r)){audit();return toast('Necesitas al menos 2 preguntas válidas en un mismo banco.')}setup(clone(r))});act('exportDraft',()=>{syncEditor();exportJSON(r)});act('exportHtml',()=>{syncEditor();if(!playable(r)){audit();return toast('Necesitas al menos 2 preguntas válidas para exportar un juego.')}exportHTML(r)});act('printDraft',()=>{syncEditor();printAnswers(r)});act('newDraft',create)}
function audit(){syncEditor();let errs=issues(draft),hard=errs.filter(x=>x.hard).length;$('audit').innerHTML=errs.length?`<strong class="${hard?'error':'success'}">${hard} errores · ${errs.length-hard} avisos</strong><details open><summary>Ver incidencias</summary>${errs.slice(0,300).map(x=>`<div>${esc(x.label)}: ${esc(x.msg)}</div>`).join('')}</details>`:'<strong class="success">✓ Todas las preguntas cumplen las comprobaciones básicas.</strong>';return hard===0}
function exportJSON(r){download(`${slug(r.title)}.json`,JSON.stringify(r,null,2))}function importText(t){t=t.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');draft=normalize(JSON.parse(t));dirty=true;editLevel=editBank=0;go('editor',true);audit();toast('Importado. Revisa las preguntas y guarda el rosco.')}
function exportHTML(r){let doc=document.documentElement.cloneNode(true);doc.querySelector('#app').innerHTML='';doc.querySelector('#toast').className='hidden';doc.querySelector('#catalog').textContent=JSON.stringify({portable:true,games:[r]}).replace(/</g,'\\u003c');doc.querySelector('title').textContent=r.title+' · Rosco LAB';doc.querySelector('body').className='';doc.querySelector('body').removeAttribute('style');doc.querySelector('body').removeAttribute('data-palette');doc.querySelector('#themeDialog').removeAttribute('open');doc.querySelector('#themeDialog').innerHTML='';doc.removeAttribute('style');download(`${slug(r.title)}-PDI.html`,'<!doctype html>\n'+doc.outerHTML,'text/html;charset=utf-8');toast('HTML autónomo preparado. Puedes abrirlo sin Internet.')}
function renderAI(){app.innerHTML=head('Taller de inteligencia artificial','Crear con IA','Configura tu rosco y elige una de las dos opciones. No necesitas claves API.')+`<div class="split"><section class="panel stack"><h2>1. Configura tu rosco</h2><div class="fields">${sel('Origen','sourceType',['PDF','Word','Texto','Tema'],'PDF')}<label class="field"><span>Materia</span><input id="aiSubject" list="aiSubjects" value="Tecnología y Digitalización"><datalist id="aiSubjects">${options(Object.keys(colors))}</datalist></label>${sel('Curso','aiCourse',courses,'3º ESO')}${sel('Dificultad','aiDifficulty',['Básica','Intermedia','Avanzada','Progresiva'],'Progresiva')}${sel('Niveles','aiLevels',['1','2','3','4'],'1')}${sel('Bancos por nivel','aiBanks',['1','2','3','4'],'1')}</div><label class="field"><span>Tema o título</span><input id="aiTitle" placeholder="Ej. Electricidad y circuitos"></label><label class="field"><span>Texto de referencia o indicaciones (opcional)</span><textarea id="aiText" rows="4" placeholder="Pega aquí tus apuntes o especifica contenidos."></textarea></label><label class="label">Letras del rosco</label>${lettersHTML(ABC)}${check('aiFact','Incluir explicaciones',true)}${check('aiStrict','Limitar al documento o texto (si se aporta)',true)}<div class="notice" id="aiCount"></div></section><section class="panel stack"><div class="row between"><h2>2. Genera tu rosco</h2><span class="pill">SIN CLAVES · V2.1</span></div><div class="row ai-tabs"><button class="primary ai-choice" id="promptTab" aria-pressed="true"><strong>OPCIÓN 1</strong><span>Crear con IA externa</span><small>Recomendada</small></button><button class="ai-choice" id="directTab" aria-pressed="false"><strong>OPCIÓN 2</strong><span>Generar en esta web</span><small>Experimental</small></button></div><div id="directPanel" class="stack hidden"><h3>Opción 2 · Generar en esta web</h3><p class="muted">Prueba a crear las preguntas sin salir de Rosco LAB. No necesitas una cuenta ni una clave. Puede que no se completen todas las letras; si ocurre, utiliza la opción 1.</p><div class="notice"><strong>Cómo hacerlo</strong><ol class="ai-steps"><li id="directStep1">Selecciona tu PDF y pulsa «Leer documento».</li><li>Deja seleccionado el método «Automático».</li><li>Pulsa «Generar borrador» y revisa las preguntas antes de guardar.</li></ol></div><div id="pdfBox" class="pdf-drop stack"><label class="field"><span id="documentLabel">Documento PDF (máx. 10 MB)</span><input type="file" id="pdfSource" accept=".pdf,application/pdf"></label><small id="pdfInfo" class="muted">Selecciona un documento con texto.</small><button id="readDocument">Leer documento</button><label id="pageBox" class="field hidden"><span>Páginas (ej. 1-3, 5; vacío = todas)</span><input id="pageRange" placeholder="Todas las páginas"></label><p id="docStatus" role="status" class="muted"></p><details id="docPreview" class="hidden"><summary>Ver texto extraído</summary><textarea id="extractedPreview" rows="6" readonly></textarea></details></div><label class="field"><span>Método de generación</span><select id="generationMethod"><option value="auto">Automático (IA local si está disponible; si no, solo definiciones)</option><option value="rules">Extracción de definiciones · sin IA</option><option value="local">IA local de Chrome · experimental</option></select></label><div class="row"><button id="checkLocal">Comprobar IA local</button><span id="localStatus" class="muted" role="status">Sin comprobar</span></div><div class="notice" id="directCost">Solo pistas de definición o preguntas completas. No se generan frases con huecos. Si faltan conceptos fiables, quedarán letras pendientes. El método usado aparece en el resultado.</div><div class="row"><button class="primary" id="directGenerate">✦ Generar borrador</button><button id="directCancel" class="hidden">Cancelar</button><button id="directPartial" class="hidden">Revisar borrador</button></div><progress id="directProgress" class="hidden" value="0" max="1"></progress><p id="directStatus" role="status" aria-live="polite" class="muted"></p><div id="candidateBox" class="hidden stack"><div id="candidateSummary" class="notice"></div><div class="row"><button id="alternativeDraft">Probar otras preguntas</button><button id="trimDraft">Usar solo letras completas</button></div><details><summary>Ver conceptos detectados</summary><div id="candidateList" class="muted"></div></details></div><small>El PDF se lee en tu navegador. Los documentos escaneados sin texto no son compatibles con esta versión. Revisa siempre el resultado y las páginas indicadas.</small></div><div class="stack" id="promptPanel"><h3>Opción 1 · Crear con IA externa</h3><p class="muted">La forma recomendada para obtener mejores preguntas. Solo tienes que copiar y pegar. No necesitas una clave API.</p><div class="ai-step"><h3><span class="ai-step-number">1</span> Copia las instrucciones (prompt)</h3><p>Rosco LAB prepara automáticamente el texto que debes enviar a la IA con la materia, el curso, las letras y las opciones que has elegido. <strong>Pulsa este botón para copiarlo entero.</strong> No tienes que escribir ni modificar nada.</p><button class="primary ai-copy" id="copyPrompt">Copiar instrucciones (prompt)</button><p id="copyStatus" class="muted" role="status" aria-live="polite">Se copiará el texto de instrucciones, no las preguntas.</p><details id="promptDetails"><summary>Ver el prompt que vas a copiar</summary><label class="field"><span>Formato de respuesta (opcional)</span><select id="aiFormat"><option value="table">Texto con columnas (recomendado)</option><option value="json">JSON Rosco LAB</option></select></label><textarea id="prompt" rows="8" readonly aria-label="Instrucciones para copiar (prompt)"></textarea></details></div><div class="ai-step"><h3><span class="ai-step-number">2</span> Abre una IA y pega las instrucciones</h3><p>Elige <strong>solo una</strong> de estas herramientas. Se abrirá en otra pestaña.</p><div id="pdfServices" class="notice"><strong>Para trabajar con PDF sin registro inicial anunciado</strong><div class="row" style="margin-top:8px"><a class="btn" href="https://www.chatpdf.com/es" target="_blank" rel="noopener noreferrer">ChatPDF ↗</a><a class="btn" href="https://smallpdf.com/es/chat-pdf" target="_blank" rel="noopener noreferrer">Smallpdf ↗</a></div><small>Pueden tener límites gratuitos o pedir registro después.</small></div><p><strong>O utiliza tu IA habitual:</strong></p><div class="row"><a class="btn" href="https://chatgpt.com/" target="_blank" rel="noopener noreferrer">ChatGPT ↗</a><a class="btn" href="https://gemini.google.com/" target="_blank" rel="noopener noreferrer">Gemini ↗</a><a class="btn" href="https://claude.ai/" target="_blank" rel="noopener noreferrer">Claude ↗</a></div><div class="notice" id="aiInstructions"></div><small>Son herramientas externas. No adjuntes documentos con datos personales del alumnado.</small></div><div class="ai-step"><h3><span class="ai-step-number">3</span> Copia las preguntas y vuelve aquí</h3><p>Cuando la IA termine, copia <strong>toda su respuesta</strong> (preguntas y soluciones). Regresa a esta pestaña y pégala en el recuadro de abajo. No hace falta descargar ningún archivo.</p><button id="goImport">Ir al recuadro para pegar preguntas ↓</button></div></div></section></div><section id="aiImportSection" class="panel stack" style="margin-top:16px"><h2>3. Pega las preguntas de la IA</h2><p>Haz clic dentro del recuadro y pulsa <strong>Ctrl + V</strong> (o ⌘ + V en Mac). Después pulsa <strong>Comprobar preguntas</strong>, revisa el resultado, abre el editor y guarda tu rosco.</p><textarea id="importText" rows="6" aria-label="Pega aquí la respuesta completa de la IA" placeholder="Pega aquí la respuesta completa de la IA (preguntas y respuestas)…"></textarea><div class="row" style="margin-top:10px"><button class="primary" id="importPaste">Comprobar preguntas</button><button id="importFile">Abrir JSON, CSV o TXT</button><input type="file" id="aiFile" accept=".json,.csv,.tsv,.txt,.md,application/json,text/plain,text/csv" hidden></div><p id="importError" class="error" role="alert"></p><div id="importReport" class="hidden stack"></div></section>`;bindLetters();app.oninput=()=>{if(view==='ai'){updatePrompt();if($('importReport'))$('importReport').classList.add('hidden')}};app.onchange=()=>{if(view==='ai'){updatePrompt();if($('importReport'))$('importReport').classList.add('hidden')}};act('copyPrompt',async()=>{try{await navigator.clipboard.writeText(val('prompt'));$('copyStatus').textContent='¡Instrucciones copiadas! Ahora elige una IA en el paso 2.';toast('Prompt copiado.')}catch{$('promptDetails').open=true;$('prompt').focus();$('prompt').select();$('copyStatus').textContent='Texto seleccionado. Pulsa Ctrl + C (o ⌘ + C en Mac) para copiarlo.';toast('Seleccionado: pulsa Ctrl+C para copiar.')}});act('goImport',()=>{$('importText').scrollIntoView({block:'center'});$('importText').focus({preventScroll:true})});act('importPaste',previewExternal);act('importFile',()=>$('aiFile').click());$('aiFile').onchange=async()=>{try{if(!$('aiFile').files[0])return;$('importText').value=await $('aiFile').files[0].text();previewExternal()}catch(e){$('importError').textContent=e.message}};bindDirect();switchAI(false);updatePrompt()}
function updatePrompt(){let ls=picked(),n=Number(val('aiLevels')),b=Number(val('aiBanks')),src=val('sourceType'),r=newRosco(ls,n,b);r.title=val('aiTitle')||'Mi rosco educativo';r.subject=val('aiSubject');r.course=val('aiCourse');r.color=colors[r.subject]||'#4f46e5';let sample={schema:r.schema,title:r.title,subject:r.subject,course:r.course,author:'',description:'Descripción breve',color:r.color,letters:ls,levels:r.levels.map(l=>({name:l.name,banks:l.banks.map(b=>({name:b.name,questions:[]}))}))};$('aiCount').textContent=`${ls.length} letras × ${n} niveles × ${b} bancos = ${ls.length*n*b} preguntas. ${ls.length<2?'Selecciona al menos 2 letras.':''}`;$('copyPrompt').disabled=ls.length<2;$('pdfServices').classList.toggle('hidden',src!=='PDF');$('aiInstructions').textContent=['PDF','Word'].includes(src)?'En la IA que has abierto, adjunta tu '+(src==='PDF'?'PDF':'archivo Word')+'. Después haz clic en su cuadro de mensaje, pulsa Ctrl + V (o ⌘ + V en Mac) para pegar las instrucciones que has copiado y envíalas. Espera a que genere las preguntas.':src==='Texto'?'Asegúrate de haber pegado tus apuntes en la configuración del rosco. Después copia las instrucciones del paso 1, pégalas en el cuadro de mensaje de la IA con Ctrl + V (o ⌘ + V en Mac) y envíalas.':'Pega las instrucciones copiadas en el cuadro de mensaje de la IA con Ctrl + V (o ⌘ + V en Mac) y envíalas.';$('directStep1').textContent=src==='Tema'?'Escribe el tema. Para generar sin documento, necesitas IA local compatible.':src==='Texto'?'Pega tus apuntes en la configuración o selecciona un archivo TXT.':`Selecciona tu ${src==='PDF'?'PDF':'archivo Word'} y pulsa «Leer documento».`;$('prompt').value=`Actúa como docente especialista. Genera un rosco educativo compatible con Rosco LAB.\nMateria: ${r.subject}\nCurso: ${r.course}\nTítulo: ${r.title}\nDificultad: ${val('aiDifficulty')}\nOrigen: ${src}\n${val('aiText')?'Contenido/indicaciones:\n'+val('aiText')+'\n':''}${['PDF','Word'].includes(src)?'Lee el documento adjunto a esta conversación.\n':''}${src!=='Tema'&&$('aiStrict').checked?'Usa exclusivamente la información del material aportado. Si no puedes construir alguna letra, omítela e incluye todas las demás; no inventes hechos.\n':''}Crea ${n} niveles y ${b} bancos diferentes por nivel. Intenta incluir una pregunta por cada letra de ${ls.join(', ')} en ese orden. Objetivo: ${ls.length*n*b} preguntas. Si no existe una respuesta fiable, omite la letra y continúa con las demás. No repitas respuestas en un banco ni entre bancos del mismo nivel. Prioridad obligatoria: busca primero respuestas que EMPIECEN por cada letra (mode "starts"). Solo usa "contains" si tras buscar otras alternativas no existe un concepto inicial adecuado en el material. Revisa todas las letras, niveles y bancos antes de devolver el resultado. Respeta la Ñ como letra distinta de N. Redacta pistas de definición autónomas, como en Pasapalabra, o preguntas completas. Ejemplo: Unidad de medida de la intensidad eléctrica. Respuesta: Amperio. Prohibido completar frases, rellenar huecos, sustituir palabras por guiones, copiar fragmentos incompletos o usar pistas vagas. Si no hay un concepto válido, no lo fuerces. Enunciados claros y sin incluir la solución. aliases: alternativas completas válidas o []. ${$('aiFact').checked?'Incluye una explicación en fact.':'Deja fact como cadena vacía.'} En source cita la página del PDF si es verificable, o deja vacío. No inventes referencias.\n${val('aiFormat')==='json'?'Devuelve solo JSON válido con esta estructura. Rellena CADA array questions con objetos {letter, mode, clue, answer, fact, aliases, source}. Conserva todos los niveles y bancos en el orden indicado, incluso si alguno está vacío. No devuelvas solo el primer nivel.\n'+JSON.stringify(sample,null,2):exchangeInstructions()}\nSi la respuesta es demasiado larga, devuelve un banco cada vez con sus números correctos; después el docente podrá completar el resto desde el editor.`;refreshDirect()}
// V1.5: exchange format, tolerant parsing and non-destructive repair.
function exchangeInstructions(){return 'Devuelve exclusivamente texto plano dentro de un único bloque de código, NO una tabla Markdown. Una línea por pregunta, sin saltos dentro de una pregunta. Separa las 8 columnas mediante | sin escapar las barras. Cabecera exacta: Nivel | Banco | Letra | Tipo | Pregunta | Respuesta | Explicación | Fuente. Usa ÚNICAMENTE números enteros en Nivel y Banco (1, 2, 3, 4), nunca nombres como Básico o Banco A. Ejemplo de formato (no copies esta pregunta): 1 | 1 | A | Empieza | Unidad de medida de la intensidad de corriente eléctrica. | Amperio | Su símbolo es A. | . Deja vacías las celdas opcionales, sin eliminar sus separadores. No incluyas filas sin respuesta ni barras dentro de las celdas. Tipo: Empieza o Contiene. No incluyas la indicación de letra dentro de la pista. Conserva el número real de nivel y banco aunque omitas preguntas. No reinicies la numeración de niveles.'}
function unmark(s){return String(s??'').replace(/[\u200B-\u200D\u2060\uFEFF]/g,'').trim().replace(/^[*`_]+|[*`_]+$/g,'').trim()}
