function reportExchange(out,remaining,actionLabel){return `<div class="notice"><strong>${out.accepted} preguntas aceptadas · ${remaining} pendientes de completar o revisar</strong><p class="muted">${out.rejected.length} filas no aplicadas · ${out.ignored} líneas no reconocidas. El tipo de pista se calcula a partir de la respuesta. Comprueba también la exactitud del contenido y las fuentes.</p><div class="import-level-summary">${out.r.levels.map((l,i)=>`<div><strong>${esc(l.name)}</strong> · ${l.banks.map((b,j)=>`${esc(b.name)}: ${b.questions.filter(q=>q.clue&&q.answer&&fits(q)).length}/${b.questions.length}`).join(" · ")}</div>`).join("")}</div>${out.rejected.length?`<details><summary>Ver motivos</summary>${out.rejected.slice(0,200).map(x=>`<div>${esc(x)}</div>`).join('')}</details>`:''}</div><div class="scroll"><table><thead><tr><th>Ubicación</th><th>Tipo</th><th>Pregunta</th><th>Respuesta</th></tr></thead><tbody>${out.r.levels.flatMap((l,i)=>l.banks.flatMap((b,j)=>b.questions.filter(q=>out.changed.has(`${i+1}/${j+1}/${q.letter}`)).map(q=>`<tr><td>${i+1}/${j+1}/${q.letter}</td><td>${q.mode==='starts'?'Empieza':'Contiene'}</td><td>${esc(q.clue)}</td><td>${esc(q.answer)}</td></tr>`))).join('')}</tbody></table></div><button class="primary" id="applyExchange" ${!out.accepted?'disabled':''}>${actionLabel}</button>`}
